import time, numpy as np, statistics
from scipy import sparse

def time_eigs(n, density, ncv):
    times=[]
    for seed in range(10):
        A=sparse.random(n,n,density=density, format='csr', random_state=seed)
        v0=np.ones(n)
        t=time.perf_counter();
        sparse.linalg.eigs(A,k=5,v0=v0,ncv=ncv,maxiter=n*200);
        times.append(time.perf_counter()-t)
    return statistics.mean(times)

for ncv in [20,25,30,40,50]:
    print(ncv, time_eigs(300,0.01,ncv))
